function trasforma(input){
  var C = { USD: 1.08, GBP: 0.86, CHF: 0.94, EUR: 1 };
  var s = String(input.Importo);
  var n = (input.Valuta === 'USD' || input.Valuta === 'GBP') ? parseFloat(s.replace(/,/g, '')) : parseFloat(s.replace(/\./g, '').replace(',', '.'));
  return { importo_eur: Math.round(n / C[input.Valuta] * 100) / 100 };
}

ref_py:
CAMBI = {'USD': 1.08, 'GBP': 0.86, 'CHF': 0.94, 'EUR': 1.0}

def trasforma(campi):
    s, v = str(campi['Importo']), campi['Valuta']
    n = float(s.replace(',', '')) if v in ('USD', 'GBP') else float(s.replace('.', '').replace(',', '.'))
    return {'importo_eur': round(n / CAMBI[v], 2)}
